def normalize_filename(filename):
    return ''.join(c for c in filename if not unicodedata.combining(c)).encode('ascii', 'ignore').decode()

def task_func(directory):
    result = {}
    for root, _, files in os.walk(directory):
        for file in files:
            normalized_file_name = normalize_filename(file)
            filepath = pathlib.Path(root) / file
            file_size = os.path.getsize(filepath)
            file_md5_hash = md5()
            with open(filepath, 'rb') as f:
                while True:
                    data = f.read(4096)
                    if not data:
                        break
                    file_md5_hash.update(data)
            result[normalized_file_name] = {'Size': file_size, 'MD5 Hash': file_md5_hash.hexdigest()}
