        raise ValueError("Input must be greater than or equal to 1")
    return [(i, j) for i in range(1, n+1) for j in range(i+1, n+1)]

from sklearn.preprocessing import MinMaxScaler
import numpy as np

def task_func(myList):
    scaler = MinMaxScaler()
    scaled_list = scaler.fit_transform(np.array(myList).reshape(-1, 1))
    return scaled_list.flatten()

import numpy as np
import pandas as pd
import statistics

def task_func(rows, columns=['A', 'B', 'C', 'D', 'E', 'F'], seed=42):
    if not isinstance(rows, int) or rows <= 0:
        raise ValueError("rows must be a positive integer greater than 0")

    rng = np.random.default_rng(seed)
    df = pd.DataFrame(rng.integers(1, 101, size=(rows, len(columns))), columns=columns)
    means = {col: statistics.mean(df[col]) for col in columns}
    medians = {col: statistics.median(df[col]) for col in columns}
    return df, {'column_name': {'mean': value, 'median': value} for column_name, value in zip(columns, [means, medians].pop())}

import os
import shutil

def task_func(path, delimiter="/"):
    if not isinstance(path, str) or not path.strip():
        raise ValueError("Invalid path")
    try:
        root = os.path.splitdrive(path)[0] + delimiter
        return [(os.path.relpath(p, root), compute_disk_usage(p)) for p in path.split(delimiter)]
    except FileNotFoundError:
        raise FileNotfoundError("File not found")

def compute_disk_usage(path):
    total, used, free = shutil.disk_usage(path)
    return {"total": total, "used": used, "free": free}
